#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    size_t capacity;   /* total slots (capacity > 0)   */
    size_t size;       /* bytes currently stored        */
    size_t head;       /* next write index              */
    size_t tail;       /* next read index               */
    uint8_t *storage;  /* the backing buffer            */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = calloc(capacity, sizeof(uint8_t));   /* zeroed storage */
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity  = capacity;
    rb->size      = 0;
    rb->head      = 0;
    rb->tail      = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    /* Space available = capacity - filled */
    size_t avail = rb->capacity - rb->size;
    if (avail == 0)
        return 0;

    size_t to_write = len < avail ? len : avail;   /* at most what fits */
    size_t until_end = rb->capacity - rb->head;      /* bytes to end of buffer */

    if (to_write <= until_end) {
        /* All fit before wrapping */
        memcpy(rb->storage + rb->head, data, to_write);
        rb->head += to_write;
    } else {
        /* Copy in two chunks: head...end, then start...tail-1  */
        memcpy(rb->storage + rb->head, data, until_end);
        memcpy(rb->storage, data + until_end, to_write - until_end);
        rb->head = to_write - until_end;
    }
    rb->size += to_write;
    return to_write;
}

static size_t read_chunk(ringbuf_t *rb, uint8_t *out, size_t offset, size_t n)
{
    if (n == 0 || offset >= rb->capacity)
        return 0;

    size_t until_end = rb->capacity - offset;
    size_t first_part = until_end < n ? until_end : n;

    memcpy(out, rb->storage + offset, first_part);
    out += first_part;

    size_t second = n - first_part;
    if (second > 0)
        memcpy(out, rb->storage, second);

    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    size_t avail = rb->size;
    if (avail == 0)
        return 0;

    size_t to_read = len < avail ? len : avail;   /* at most what is stored */
    read_chunk(rb, out, rb->tail, to_read);

    rb->tail += to_read;
    rb->size -= to_read;
    if (rb->tail == rb->capacity)       /* wrap back */
        rb->tail = 0;                    /* capacity > 0 here */
    return to_read;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    size_t avail = rb->size;
    if (avail == 0)
        return 0;

    size_t to_copy = len < avail ? len : avail;
    read_chunk((ringbuf_t *)rb, out, rb->tail, to_copy);   /* cast OK: we don't modify */
    return to_copy;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

#define CHECK(cond, msg) do { \
    if (!(cond)) { fprintf(stderr, "FAIL: %s\n", msg); return 1; } \
} while (0)

int main(void)
{
    /* --- rb_create / rb_capacity / rb_size --- */
    ringbuf_t *rb = rb_create(8);
    CHECK(rb != NULL, "create");
    CHECK(rb_capacity(rb) == 8, "capacity");

    /* --- rb_write fills buffer --- */
    const uint8_t hello[] = {'h','e','l','l','o'};
    size_t n = rb_write(rb, hello, sizeof(hello));
    CHECK(n == 5, "write 5 bytes");
    CHECK(rb_size(rb) == 5, "size after write");

    /* --- rb_read returns oldest first --- */
    uint8_t buf[6];
    n = rb_read(rb, buf, 6);        /* request more than stored */
    CHECK(n == 5, "read all");
    CHECK(memcmp(buf, hello, 5) == 0, "data match");

    /* buffer now empty */
    CHECK(rb_size(rb) == 0, "size after read");

    /* --- rb_write again (tail/head reset to 0 after clear of size=0) --- */
    const uint8_t world[] = {'w','o','r','l','d'};
    n = rb_write(rb, world, sizeof(world));
    CHECK(n == 5, "write2");

    /* --- wrap-around write --- */
    memset(buf, 0, sizeof(buf));
    size_t cap = rb_capacity(rb);   /* 8 */
    size_t remaining = cap - rb_size(rb); /* 3 */

    /* Write enough to force wrap: fill rest, then some more */
    uint8_t extra[10];
    memcpy(extra, world + 5, 0);   /* just padding */
    memset(extra, 'A', sizeof(extra));
    n = rb_write(rb, extra, sizeof(extra));
    CHECK(n == remaining, "write with wrap: wrote exactly what fit");

    /* --- peek returns oldest without consuming --- */
    size_t ps = rb_peek(rb, buf, 1);
    CHECK(ps == 1, "peek count");
    CHECK(buf[0] == 'w', "peek data");
    CHECK(rb_size(rb) == cap, "size unchanged after peek");

    /* --- clear --- */
    rb_clear(rb);
    CHECK(rb_size(rb) == 0, "clear size");
    CHECK(rb_capacity(rb) == 8, "capacity after clear");

    /* --- round-trip: fill then drain with wrap --- */
    uint8_t pattern[12];
    for (size_t i = 0; i < 12; ++i) pattern[i] = (uint8_t)(i + 1);

    n = rb_write(rb, pattern, 8);       /* fill to full */
    CHECK(n == 8, "fill full");
    n = rb_write(rb, pattern, 4);       /* should write 0 */
    CHECK(n == 0, "write when full");

    uint8_t drain[12];
    n = rb_read(rb, drain, 12);         /* read all 8 that are stored */
    CHECK(n == 8, "read all filled");
    CHECK(memcmp(drain, pattern, 8) == 0, "drain matches write");

    /* --- NULL safety --- */
    CHECK(rb_write(NULL, hello, 5) == 0, "wNULL");
    CHECK(rb_read(NULL, buf, 6) == 0, "rNULL");
    CHECK(rb_peek(NULL, buf, 1) == 0, "pNULL");
    CHECK(rb_size(NULL) == 0, "sNULL");
    CHECK(rb_capacity(NULL) == 0, "cNULL");
    rb_destroy(NULL);                   /* must not crash */

    rb_destroy(rb);

    /* --- create with capacity==0 fails --- */
    CHECK(rb_create(0) == NULL, "zero cap");

    printf("All tests passed.\n");
    return 0;
}
